import{z as s,x as i,o as n,c as d,q as r,j as o,D as a,d as A,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Double ML 的深入","description":"","frontmatter":{"title":"Double ML 的深入","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pm-dml-deep.md","filePath":"econ/pm-dml-deep.md","lastUpdated":1791413859000}'),m={name:"econ/pm-dml-deep.md"};function D(p,E,h,u,c,C){const t=i("Mermaid");return n(),d("div",null,[E[2]||(E[2]=r('<h1 id="double-ml-的深入" tabindex="-1">Double ML 的深入 <a class="header-anchor" href="#double-ml-的深入" aria-label="Permalink to &quot;Double ML 的深入&quot;">​</a></h1><div class="epigraph"><p>DML 的两根柱子各管一件事：正交把讨厌函数的速率要求放宽，交叉拟合把过拟合的偏倚赶回独立样本——少任何一根，灵活模型都会把偏倚伪装成效应。</p><footer>—— 据 Chernozhukov, Chetverikov, Demirer, Duflo, Hansen, Newey and Robins, Double/Debiased Machine Learning, Econometrics Journal 2018 整理</footer></div><p><a href="/econ/pm-ml-causal-deep">上一课</a>把因果 ML 的地图与元学习器铺开，DR-学习器被押后到本课。主干课<a href="/econ/ml-causal-econ">机器学习与因果</a>与量化栏的<a href="/quant/double-machine-learning">双重机器学习 DML</a>都钉过：Neyman 正交得分加交叉拟合，让灵活 ML 估讨厌函数时低维目标仍可 \\(\\sqrt n\\) 推断。本课深入三处：正交性的来源、异质效应的 DR-学习器、以及实施清单里最容易翻车的偏差源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>部分线性模型 \\(y=\\theta d+g(x)+u\\)。朴素做法——ML 预测 \\(y\\)、ML 预测 \\(d\\)、残差对残差回归——何时失效？两条伤。其一，讨厌函数估计不够快时，\\(\\hat g-g\\) 与 \\(\\hat m-m\\) 的交叉项以 \\(\\sqrt n\\) 可见的幅度进 \\(\\hat\\theta\\)，正则偏差直接污染目标。其二，交叉项期望为零要求残差与真实误差独立，同一样本上的过拟合破坏独立性。要问的因此不是「用不用 DML」，而是「我的收敛率与划分方案够不够撑起 \\(\\sqrt n\\)」。</p><p><span class="marginnote">术语翻译：讨厌函数（nuisance）指为了拿到答案不得不估、但本身不是答案的那些函数——这里是控制变量如何影响结局的 \\(g(x)\\) 和处理如何被分配的 \\(m(x)\\)。它们像做菜用的水和油：必须经手，但没人进餐厅是为了点一杯油。</span></p><h3 id="正交性从哪来" tabindex="-1">正交性从哪来 <a class="header-anchor" href="#正交性从哪来" aria-label="Permalink to &quot;正交性从哪来&quot;">​</a></h3><p>Neyman 正交是得分对讨厌函数的 Gateaux 导数为零：讨厌函数的一阶估计误差不进目标，速率要求从 \\(\\sqrt n\\) 放宽到 \\(n^{-1/4}\\)，灵活 ML 够得着。这个思想在 Neyman 的 C(α) 统计量与 Robins–Rotnitzky 的双重稳健估计里已有雏形，DML 把它工程化。ATE 的 AIPW 得分更进一层：倾向得分与条件回归两个讨厌函数其一达到 \\(\\sqrt n\\) 即可——双重稳健。部分线性的残差化可上溯 Robinson 1988。</p><p><span class="marginnote">数字实例：\\(n=10^4\\) 时，\\(\\sqrt n\\) 速率要求讨厌函数误差缩到 \\(0.01\\)，而 \\(n^{-1/4}\\) 只要求 \\(0.1\\)——宽松整整十倍。DML 的意义就是把对机器学习模型的门槛从「非参精度做到 0.01」（大多数算法做不到）降到「0.1 就够」（普通算法够得着），代价要靠第二根柱子来付。</span></p><h3 id="dr-学习器与交叉拟合的账" tabindex="-1">DR-学习器与交叉拟合的账 <a class="header-anchor" href="#dr-学习器与交叉拟合的账" aria-label="Permalink to &quot;DR-学习器与交叉拟合的账&quot;">​</a></h3><p>异质效应：把 AIPW 伪结果当标签、对 \\(x\\) 做第二段回归，这是 DR-学习器（Kennedy 2023）——伪结果在「倾向正确或回归正确」之下均以 \\(\\sqrt n\\) 收敛到真效应，第二段回归只需非参速率。交叉拟合的账本：分 \\(K\\) 折，每折用其余 \\(K-1\\) 折估讨厌函数、回本折算得分，跨折的近似独立性恢复了中心极限定理的使用条件，过拟合偏倚从「样本内相关」变成「跨样本无关」。DML1 与 DML2 的差别只在得分怎么汇总——折内平均再平均，或全样本解矩条件；实现的一致性比两者之别更要紧。</p><p><span class="marginnote">AIPW 得分里 \\(1/\\hat e(x)\\) 一项在倾向得分趋近零或一时方差爆炸：先画 \\(\\hat e(x)\\) 的分布，重叠差的区域要么裁剪要么分域估计，并报告结论对截断阈值的敏感性——权重爆炸不是小样本吓唬人，是识别假设在数据上失守的信号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实施清单固定。一，目标与得分先于算法：部分线性、ATE 还是 \\(\\tau(x)\\)，得分不同。二，调参对准讨厌函数自己的损失（交叉验证），不用 \\(\\hat\\theta\\) 的稳定性当标准——后者把正则偏差藏进选择。三，\\(K=5\\) 起步；面板与聚类数据按时间块或聚类切分，不随机切。四，得分裁剪极端值并报敏感性。五，报告四件：得分均值与标准误、讨厌函数的样本外表现、朴素样本内估计与 DML 的差、截断敏感性。最后一件常被省略：两套估计差得多，往往恰是偏差校正真的在干活，而不是哪一套错了。</p>',14)),(n(),o(B,null,{default:a(()=>[l(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%AE%9A%E6%A8%A1%E5%9E%8B%E4%B8%8E%E5%BE%97%E5%88%86%3A%20%E9%83%A8%E5%88%86%E7%BA%BF%E6%80%A7%2FATE%2F%E5%BC%82%E8%B4%A8%22%5D%20--%3E%20T%5B%22ML%20%E8%B0%83%E5%8F%82%3A%20%E5%AF%B9%E5%87%86%E8%AE%A8%E5%8E%8C%E5%87%BD%E6%95%B0%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20T%20--%3E%20CF%5B%22K%20%E6%8A%98%E4%BA%A4%E5%8F%89%E6%8B%9F%E5%90%88%E7%AE%97%E5%BE%97%E5%88%86%22%5D%0A%20%20CF%20--%3E%20TRIM%5B%22%E8%A3%81%E5%89%AA%E6%9E%81%E7%AB%AF%E5%80%BE%E5%90%91%E5%BE%97%E5%88%86%22%5D%0A%20%20TRIM%20--%3E%20EST%5B%22%E5%BE%97%E5%88%86%E5%9D%87%E5%80%BC%E4%B8%8E%E6%A0%87%E5%87%86%E8%AF%AF%22%5D%0A%20%20EST%20--%3E%20DIAG%5B%22%E8%AF%8A%E6%96%AD%3A%20%E8%AE%A8%E5%8E%8C%E5%87%BD%E6%95%B0%E6%A0%B7%E6%9C%AC%E5%A4%96%E4%B8%8E%E6%9C%B4%E7%B4%A0%E5%B7%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"正交为什么成立：AIPW 与部分线性得分的构造在推导里恰好把一阶变分项配平，讨厌函数的估计误差只以二阶项进入，二阶项在速率条件下被 \\(\\sqrt n\\) 吞掉。交叉拟合为什么救推断：无交叉拟合时 \\(\\hat g\\) 由同一样本估出，得分与噪声相关，中心极限定理的中心项随样本漂移；交叉拟合把这份相关换成跨折独立，\\(\\sqrt n\\) 正态重新成立。DR-学习器的机制同源：伪结果本身是目标的无偏二步估计，第二段回归消化的是剩余的非参误差。",-1)),E[5]||(E[5]=e("p",null,"两根柱子各堵住一条失效路径，合起来才通向 \\(\\sqrt n\\) 推断：",-1)),(n(),o(B,null,{default:a(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E8%AE%A8%E5%8E%8C%E5%87%BD%E6%95%B0%E4%BC%B0%E8%AE%A1%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20X%5B%22%E4%B8%8E%E6%AE%8B%E5%B7%AE%E7%9B%B8%E4%B9%98%EF%BC%9A%E4%BA%A4%E5%8F%89%E9%A1%B9%E6%B1%A1%E6%9F%93%20%CE%B8%22%5D%0A%20%20X%20--%3E%20A%5B%22%E6%AD%A3%E4%BA%A4%E6%80%A7%EF%BC%9A%E4%B8%80%E9%98%B6%E8%AF%AF%E5%B7%AE%E6%8A%B5%E6%B6%88%EF%BC%8C%E5%8F%AA%E4%BD%99%E4%BA%8C%E9%98%B6%22%5D%0A%20%20A%20--%3E%20B%5B%22%E9%80%9F%E7%8E%87%E6%9D%A1%E4%BB%B6%E4%B8%8B%E8%A2%AB%20%E2%88%9An%20%E5%90%9E%E6%8E%89%22%5D%0A%20%20E%20--%3E%20C%5B%22%E5%90%8C%E4%B8%80%E6%A0%B7%E6%9C%AC%E8%BF%87%E6%8B%9F%E5%90%88%EF%BC%9A%E5%BE%97%E5%88%86%E4%B8%8E%E5%99%AA%E5%A3%B0%E7%9B%B8%E5%85%B3%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BA%A4%E5%8F%89%E6%8B%9F%E5%90%88%EF%BC%9A%E6%8A%98%E5%A4%96%E6%A0%B7%E6%9C%AC%E6%89%93%E5%88%86%22%5D%0A%20%20D%20--%3E%20B2%5B%22%E8%B7%A8%E6%8A%98%E7%8B%AC%E7%AB%8B%EF%BC%9ACLT%20%E9%87%8D%E6%96%B0%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">直觉类比：交叉拟合像考试前不许看原题——讨厌函数在 A 卷上估，到 B 卷上打分。估错带来的偏倚与 B 卷的噪声无关，跨折平均后互相抵消；若在同一个样本上又估又测（自估自测），误差会系统性地偏向自己这边，平均不掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>识别仍是 CIA 或 IV，DML 不提供外生性；不重叠毁掉 IPW 分支，弱工具下部分线性的推断另有专门的弱工具稳健方法，正交不治弱工具。遗漏变量的敏感性分析不在此展开。机器学习 nuisance 的函数类选择决定 \\(n^{-1/4}\\) 是否现实——模型太弱，速率假设落空；模型过拟合，交叉拟合来救，但救不了系统性错设定。下一课换数据形态：当控制与结局本身是文本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DML 的两根柱：Neyman 正交把讨厌函数速率要求放到 \\(n^{-1/4}\\)，交叉拟合恢复 CLT 的独立性条件。</li><li>ATE 用 AIPW 双重稳健得分；异质效应用 DR-学习器把伪结果当标签回归。</li><li>调参对准讨厌函数损失；K 折按时间与聚类切；裁剪极端倾向得分并报敏感性。</li><li>朴素样本内估计与 DML 的差是诊断量：差得多往往说明偏差校正真的在干活。</li><li>出处：Robinson, <em>Econometrica</em> 1988；Chernozhukov, Chetverikov, Demirer, Duflo, Hansen, Newey and Robins, <em>Econometrics Journal</em> 2018；Belloni, Chernozhukov and Hansen, <em>JEP</em> 2014；Kennedy, DR-learner, <em>EJS</em> 2023。</li></ul>',5))])}const f=s(m,[["render",D]]);export{F as __pageData,f as default};
